/// Predicted class index: largest raw score, ties to the lowest class.
pub fn predict(x: &[InputType; NUM_FEATURES]) -> usize {
    argmax(&forward(x))
}

/// Predicted class index: largest raw score, ties to the lowest class.
pub fn predict_inline(x: &[InputType; NUM_FEATURES]) -> usize {
    argmax(&forward_inline(x))
}

/// `raw / OUTPUT_SCALE` is the model's raw score (log-odds or margin).
pub const OUTPUT_SCALE: f64 = 268435456.0;

/// Number of classes.
pub const NUM_CLASSES: usize = 3;
/// The original class labels, by predicted index.
pub const CLASS_LABELS: [i32; NUM_CLASSES] = [0, 1, 2];
